export function AuthPage({ mode }: { mode: 'sign-in' | 'sign-up' | 'forgot-password' }) {
  const auth = useContext(AuthContext); const [, go] = useLocation();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [name, setName] = useState('');
  const [busy, setBusy] = useState(false); const [notice, setNotice] = useState('');
  useEffect(() => { if (auth.userId) go('/dashboard'); }, [auth.userId, go]);
  const submit = async (e: FormEvent) => {
    e.preventDefault(); setNotice('');
    if (!supabase) { setNotice('Authentication is not configured yet. Please contact the agency team.'); return; }
    setBusy(true);
    try {
      if (mode === 'sign-in') { const { error } = await supabase.auth.signInWithPassword({ email, password }); if (error) throw error; go('/dashboard'); }
      else if (mode === 'sign-up') { const { error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: name } } }); if (error) throw error; setNotice('Your account is ready. Check your inbox if email confirmation is enabled, then sign in to begin your application.'); }
      else { const { error } = await supabase.auth.resetPasswordForEmail(email); if (error) throw error; setNotice('If an account exists for that email, a recovery link is on its way.'); }
    } catch (err) { setNotice(err instanceof Error ? err.message : 'Something went wrong. Please try again.'); } finally { setBusy(false); }
  };
  const title = mode === 'sign-in' ? 'Welcome back.' : mode === 'sign-up' ? 'Your story starts here.' : 'Let’s get you back in.';
  return <div className="auth-page"><aside className="auth-aside"><Brand light/><div className="auth-quote"><p>“A place to show up as yourself, and grow into what’s next.”</p><small>TRENDIE MODELS · ACCRA</small></div><div className="auth-aside-bottom">TALENT · COMMUNITY · CARE</div></aside><main className="auth-main"><Link href="/" className="auth-back">← Back to the agency</Link><div className="auth-form-wrap"><div className="eyebrow"><i/> MEMBER ACCESS</div><h1>{title}</h1><p className="auth-sub">{mode === 'sign-up' ? 'Create your member account to start an application.' : mode === 'forgot-password' ? 'Enter your account email and we’ll send a secure recovery link.' : 'Sign in to continue your agency journey.'}</p><form className="auth-form" onSubmit={submit}>{mode === 'sign-up' && <Field label="Your full name"><input required value={name} onChange={e => setName(e.target.value)} placeholder="As you’d like us to know you"/></Field>}<Field label="Email address"><input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com"/></Field>{mode !== 'forgot-password' && <Field label="Password"><input type="password" required minLength={8} value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 8 characters"/></Field>}{mode === 'sign-in' && <div className="forgot-line"><Link href="/forgot-password">Forgot password?</Link></div>}{notice && <p className="form-notice">{notice}</p>}<Button type="submit" disabled={busy} className="button-full">{busy ? 'Please wait…' : mode === 'sign-in' ? 'Sign in' : mode === 'sign-up' ? 'Create account' : 'Send recovery link'} <ArrowRight size={16}/></Button></form><p className="auth-switch">{mode === 'sign-up' ? 'Already a member?' : 'New to TRENDIE MODELS?'} <Link href={mode === 'sign-up' ? '/sign-in' : '/sign-up'}>{mode === 'sign-up' ? 'Sign in' : 'Create an account'}</Link></p><p className="auth-help">Need help? <a href="mailto:hellotrendiemodels@gmail.com">hellotrendiemodels@gmail.com</a></p></div></main></div>;
}

function initials(name?: string) { return (name || 'TM').split(' ').filter(Boolean).slice(0,2).map(s => s[0]?.toUpperCase()).join('') || 'TM'; }
function fmt(value?: string | null) { if (!value) return '—'; const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleDateString('en-GH', { month:'short', day:'numeric', year:'numeric' }); }
function Pill({ status }: { status: string }) { return <span className={`status-pill status-${status.toLowerCase().replaceAll('_','-')}`}>{status.replaceAll('_',' ')}</span>; }
function PageTitle({ title, description, eyebrow = 'YOUR AGENCY SPACE', action }: { title: string; description?: string; eyebrow?: string; action?: ReactNode }) { return <div className="page-title"><div><p className="section-kicker">{eyebrow}</p><h1>{title}</h1>{description && <p className="page-description">{description}</p>}</div>{action}</div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function LoadingState() { return <div className="loading-state"><i className="skeleton sk-title"/><i className="skeleton sk-line"/><i className="skeleton sk-card"/><i className="skeleton sk-card"/></div>; }
function ErrorState({ retry }: { retry: () => void }) { return <div className="state-card"><CircleAlert/><h3>We couldn’t load this just now</h3><p>Please check your connection and try again. Your information is still safe.</p><Button variant="outline" onClick={retry}><RefreshCw size={15}/> Try again</Button></div>; }
function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-symbol"><Sparkles size={20}/></div><h3>{title}</h3><p>{body}</p>{action}</div>; }
function Metric({ icon, label, value, hint, tone }: { icon: ReactNode; label: string; value: number | string; hint: string; tone: string }) { return <div className="metric-card"><div className={`metric-icon metric-${tone}`}>{icon}</div><div className="metric-copy"><small>{label}</small><strong>{value}</strong><span>{hint}</span></div><ArrowUpRight className="metric-arrow" size={16}/></div>; }
function TaskRow({ task, onSubmit }: { task: AgencyTask; onSubmit?: () => void }) { return <div className="task-row"><span className="task-check">{task.status === 'completed' ? <Check size={15}/> : <Clock3 size={15}/>}</span><div className="task-row-main"><b>{task.title}</b><small>{task.deadline ? `Due ${fmt(task.deadline)}` : task.description}</small></div><Pill status={task.assignment_status || task.status}/>{onSubmit && <Button variant="outline" onClick={onSubmit}>Submit</Button>}</div>; }
const modelNav = [['Overview','/dashboard',LayoutDashboard],['My profile','/profile',UserRound],['My tasks','/tasks',ClipboardList],['Points & ranking','/points',Trophy],['Messages','/messages',MessageCircle],['Announcements','/announcements',BookOpen],['Daily tracker','/daily-tracker',Activity],['Notifications','/notifications',Bell],['Support','/support',CircleHelp]] as const;
const adminNav = [['Overview','/dashboard',LayoutDashboard],['Models','/models',Users],['Applications','/applications',FileText],['Tasks','/tasks',ClipboardList],['Points','/points',Trophy],['Messages','/messages',MessageCircle],['Announcements','/announcements',BookOpen],['Notifications','/notifications',Bell],['Support','/support',CircleHelp],['Audit log','/audit-logs',ShieldCheck],['Settings','/settings',Settings]] as const;
const routeTitles: Record<string,string> = { '/dashboard':'Overview','/profile':'My profile','/models':'Models','/applications':'Applications','/tasks':'Tasks','/points':'Points & ranking','/leaderboard':'Leaderboard','/messages':'Messages','/announcements':'Announcements','/daily-tracker':'Daily tracker','/notifications':'Notifications','/support':'Support','/audit-logs':'Audit log','/settings':'Settings' };

export function ProtectedPage({ path }: { path: string }) {
  const auth = useContext(AuthContext); const profileQuery = useGetProfile<AgencyProfile>({ query: { enabled: !!auth.userId, queryKey: getGetProfileQueryKey() } }); const [, go] = useLocation(); const [open, setOpen] = useState(false);
  useEffect(() => { if (!auth.loading && !auth.userId) go('/sign-in'); }, [auth.loading, auth.userId, go]);
  if (auth.loading || (auth.userId && profileQuery.isLoading)) return <div className="protected-loading"><div className="shell-skeleton"/><LoadingState/></div>;
  if (!auth.userId) return null;
  if (profileQuery.isError) return <div className="standalone-state"><ErrorState retry={() => profileQuery.refetch()}/></div>;
  const profile = profileQuery.data; if (!profile) return null;
  const admin = profile.role === 'admin';
  if (!admin && ['/models','/applications','/audit-logs','/settings'].includes(path)) return <div className="standalone-state"><EmptyState title="This space is for the agency team." body="Your member dashboard is ready for you." action={<Link href="/dashboard" className="button button-primary">Back to overview</Link>}/></div>;
  const currentTitle = routeTitles[path] || 'Agency space';
  return <div className="app-shell"><aside className={`sidebar ${open ? 'sidebar-open' : ''}`}><div className="sidebar-brand"><Brand light/><button className="mobile-close" onClick={() => setOpen(false)} aria-label="Close navigation"><X/></button></div><div className="sidebar-kicker">{admin ? 'AGENCY CONSOLE' : 'MEMBER SPACE'}</div><nav className="side-nav">{(admin ? adminNav : modelNav).map(([label, href, Icon]) => <Link href={href} key={href} className={`side-link ${path === href || (path === '/leaderboard' && href === '/points') ? 'side-link-active' : ''}`} onClick={() => setOpen(false)}><Icon size={18}/><span>{label}</span></Link>)}</nav><div className="sidebar-bottom"><div className="sidebar-help"><CircleHelp/><div><b>Need a hand?</b><small>Our team is here for you.</small></div><Link href="/support"><ArrowUpRight size={16}/></Link></div><div className="user-mini"><span className="avatar">{initials(profile.full_name)}</span><div className="user-mini-text"><b>{profile.full_name || 'Member'}</b><small>{admin ? 'Agency admin' : 'Agency member'}</small></div><button aria-label="Sign out" onClick={async () => { await supabase?.auth.signOut(); go('/'); }}><LogOut size={16}/></button></div></div></aside>{open && <button className="mobile-scrim" onClick={() => setOpen(false)} aria-label="Close menu"/>}<div className="main-column"><header className="app-topbar"><button className="mobile-menu" onClick={() => setOpen(true)} aria-label="Open menu"><Menu/></button><div className="breadcrumb"><span>Agency space</span><ChevronRight size={14}/><b>{currentTitle}</b></div><div className="topbar-tools"><span className="today-label">{new Date().toLocaleDateString('en-GH',{weekday:'short',month:'short',day:'numeric'})}</span><Link href="/notifications" className="top-icon"><Bell size={18}/></Link><Link href="/profile" className="top-avatar">{initials(profile.full_name)}</Link></div></header><main className="page-content"><RouteScreen path={path} profile={profile} admin={admin}/></main></div></div>;
}

function RouteScreen({ path, profile, admin }: { path: string; profile: AgencyProfile; admin: boolean }) {
  switch (path) {
    case '/dashboard': return <Dashboard profile={profile} admin={admin}/>;
    case '/profile': return <Profile profile={profile}/>;
    case '/models': return <Models/>;
    case '/applications': return <Applications/>;
    case '/tasks': return <Tasks admin={admin}/>;
    case '/points': case '/leaderboard': return <Points admin={admin}/>;
    case '/messages': return <Messages profile={profile} admin={admin}/>;
    case '/announcements': return <Announcements admin={admin}/>;
    case '/daily-tracker': return <Tracker/>;
    case '/notifications': return <Notifications/>;
    case '/support': return <Support admin={admin}/>;
    case '/audit-logs': return <Audit/>;
    case '/settings': return <SettingsPage profile={profile}/>;
    default: return <EmptyState title="This page isn’t available." body="Use the navigation to find your way around." action={<Link href="/dashboard" className="button button-primary">Go to overview</Link>}/>;
  }
}

function Dashboard({ profile, admin }: { profile: AgencyProfile; admin: boolean }) {
  const { data, isLoading, isError, refetch } = useGetDashboard();
  if (isLoading) return <LoadingState/>; if (isError || !data) return <ErrorState retry={() => refetch()}/>;
  return <><PageTitle eyebrow={admin ? 'AGENCY AT A GLANCE' : 'YOUR AGENCY SPACE'} title={admin ? 'Good to see you.' : `Welcome, ${profile.full_name.split(' ')[0]}.`} description={admin ? 'A clear view of what needs your attention today.' : 'Your next steps, all in one place.'} action={<Link href={admin ? '/applications' : '/profile'} className="button button-primary">{admin ? 'Review applications' : 'Complete your profile'} <ArrowRight size={16}/></Link>}/>
    {!admin && profile.application_status !== 'approved' && <div className="application-banner"><div className="banner-icon"><FileText/></div><div><b>{profile.application_status === 'pending' ? 'Your application is with our team.' : profile.application_status === 'rejected' ? 'Your application needs another look.' : 'Your agency journey begins with an application.'}</b><p>{profile.application_status === 'pending' ? 'We’ll keep you updated as soon as there’s news.' : profile.review_reason || 'Complete your profile and share a little about yourself to apply.'}</p></div><Pill status={profile.application_status}/>{profile.application_status !== 'pending' && <Link href="/profile" className="text-link">Continue <ArrowRight size={15}/></Link>}</div>}
    <div className="metric-grid">{admin ? <><Metric icon={<Users/>} label="Models" value={data.total_models} hint={`${data.approved_models} approved`} tone="olive"/><Metric icon={<FileText/>} label="Applications" value={data.pending_applications} hint="Awaiting review" tone="sand"/><Metric icon={<ClipboardList/>} label="Active tasks" value={data.tasks} hint={`${data.completed_tasks} completed`} tone="peach"/><Metric icon={<CircleHelp/>} label="Support requests" value={data.support_requests} hint="Across the agency" tone="blue"/></> : <><Metric icon={<Trophy/>} label="Points earned" value={profile.points} hint={data.leaderboard_position ? `Ranked #${data.leaderboard_position}` : 'Keep building momentum'} tone="olive"/><Metric icon={<ClipboardList/>} label="Your tasks" value={data.tasks} hint={`${data.completed_tasks} completed`} tone="sand"/><Metric icon={<MessageCircle/>} label="Messages" value={data.unread_messages} hint="Unread conversations" tone="peach"/><Metric icon={<Bell/>} label="Notifications" value={data.unread_notifications} hint="Updates for you" tone="blue"/></>}</div>
    <div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><p className="section-kicker">UP NEXT</p><h2>{admin ? 'Agency pulse' : 'Upcoming tasks'}</h2></div><Link href={admin ? '/models' : '/tasks'} className="panel-link">View all <ArrowRight size={15}/></Link></div>{admin ? <div className="quick-links"><Link href="/applications"><span className="quick-icon"><FileText/></span><span><b>Applications to review</b><small>{data.pending_applications} waiting for a decision</small></span><ChevronRight/></Link><Link href="/support"><span className="quick-icon"><CircleHelp/></span><span><b>Support requests</b><small>{data.support_requests} conversations in progress</small></span><ChevronRight/></Link><Link href="/announcements"><span className="quick-icon"><BookOpen/></span><span><b>Keep the community in the loop</b><small>Share a new agency announcement</small></span><ChevronRight/></Link></div> : data.upcoming_tasks.length ? <div>{data.upcoming_tasks.slice(0,4).map(t => <TaskRow key={t.id} task={t}/>)}</div> : <EmptyState title="A little breathing room." body="There are no upcoming tasks right now. New assignments will appear here."/>}</section>
      <section className="panel"><div className="panel-head"><div><p className="section-kicker">FROM THE AGENCY</p><h2>Latest notes</h2></div><Link href="/announcements" className="panel-link">All notes <ArrowRight size={15}/></Link></div>{data.announcements.length ? data.announcements.slice(0,3).map(a=><article className="announcement-mini" key={a.id}><span className="announcement-mark"><BookOpen size={17}/></span><div><h3>{a.title}</h3><p>{a.body}</p><small>{fmt(a.created_at)}</small></div></article>) : <EmptyState title="A quiet bulletin board." body="Agency news will show here when it’s shared."/>}</section></div>
    <section className="panel activity-panel"><div className="panel-head"><div><p className="section-kicker">RECENT ACTIVITY</p><h2>{admin ? 'Agency activity' : 'Your recent progress'}</h2></div></div>{data.recent_activity.length ? data.recent_activity.slice(0,5).map((item,i)=><div className="activity-row" key={i}><i/><span>{String(item['description'] || item['action'] || 'Agency activity')}</span><small>{item['created_at'] ? fmt(String(item['created_at'])) : 'Recently'}</small></div>) : <p className="quiet-line">Your new activity will appear here.</p>}</section>
  </>;
}

function Profile({ profile }: { profile: AgencyProfile }) {
  const qc = useQueryClient(); const update = useUpdateProfile(); const submitApp = useSubmitApplication();
  const [form,setForm] = useState({ full_name:profile.full_name||'', phone:profile.phone||'', date_of_birth:profile.date_of_birth||'', location:profile.location||'', height_cm:profile.height_cm?.toString()||'', biography:profile.biography||'', experience:profile.experience||'' });
  const [notice,setNotice] = useState(''); const [statement,setStatement] = useState('');
  useEffect(()=>setForm({ full_name:profile.full_name||'', phone:profile.phone||'', date_of_birth:profile.date_of_birth||'', location:profile.location||'', height_cm:profile.height_cm?.toString()||'', biography:profile.biography||'', experience:profile.experience||'' }),[profile]);
  const save = (e:FormEvent)=>{e.preventDefault();update.mutate({data:{full_name:form.full_name,phone:form.phone||null,date_of_birth:form.date_of_birth||null,location:form.location||null,height_cm:form.height_cm?Number(form.height_cm):null,biography:form.biography||null,experience:form.experience||null}},{onSuccess:p=>{qc.setQueryData(getGetProfileQueryKey(),p);setNotice('Your profile has been updated.');},onError:()=>setNotice('Your changes could not be saved. Please try again.')});};
  const application = (e:FormEvent)=>{e.preventDefault();submitApp.mutate({data:{statement:statement||null}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getGetProfileQueryKey()});qc.invalidateQueries({queryKey:getListApplicationsQueryKey()});setNotice('Your application has been sent to our review team.');},onError:()=>setNotice('Your application could not be submitted. Please try again.')});};
  return <><PageTitle title="Your profile" description="Help us understand who you are and where you’d like to go."/><div className="profile-layout"><aside className="panel profile-summary"><div className="profile-photo-slot"><Camera/><span>Photo slot</span><small>Portrait image</small></div><h2>{profile.full_name||'Your name'}</h2><p>{profile.location||'Add your location'}</p><Pill status={profile.application_status}/><div className="completion"><div><span>Profile completion</span><b>{profile.profile_completion}%</b></div><div className="progress-track"><i style={{width:`${Math.min(100,profile.profile_completion)}%`}}/></div><small>A complete profile helps our team get to know you.</small></div><div className="points-preview"><Trophy/><span><b>{profile.points}</b><small>agency points</small></span></div>{profile.review_reason&&<div className="review-note"><b>Team feedback</b><p>{profile.review_reason}</p></div>}</aside>
    <div className="profile-right"><form className="panel profile-form" onSubmit={save}><div className="panel-head"><div><p className="section-kicker">PERSONAL DETAILS</p><h2>The essentials</h2></div><span className="privacy-note"><ShieldCheck size={15}/> Private to the agency</span></div><div className="form-grid"><Field label="Full name"><input required value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></Field><Field label="Email address"><input disabled value={profile.email}/></Field><Field label="Phone number"><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="+233"/></Field><Field label="Date of birth"><input type="date" value={form.date_of_birth} onChange={e=>setForm({...form,date_of_birth:e.target.value})}/></Field><Field label="Location"><input value={form.location} onChange={e=>setForm({...form,location:e.target.value})} placeholder="Accra, Ghana"/></Field><Field label="Height (cm)"><input type="number" min="0" max="260" value={form.height_cm} onChange={e=>setForm({...form,height_cm:e.target.value})} placeholder="e.g. 172"/></Field><Field label="Experience"><textarea rows={3} value={form.experience} onChange={e=>setForm({...form,experience:e.target.value})} placeholder="Tell us about your experience so far"/></Field><Field label="A little about you"><textarea rows={4} value={form.biography} onChange={e=>setForm({...form,biography:e.target.value})} placeholder="Your story, interests, and what you’re excited to explore"/></Field></div>{notice&&<p className="form-notice">{notice}</p>}<div className="form-footer"><span>Only share details you’re comfortable sharing.</span><Button disabled={update.isPending}>{update.isPending?'Saving…':'Save changes'} <Check size={16}/></Button></div></form>
    {profile.application_status==='not_submitted'||profile.application_status==='rejected' ? <form className="panel application-submit" onSubmit={application}><div><p className="section-kicker">YOUR APPLICATION</p><h2>{profile.application_status==='rejected'?'Update your application':'Ready to introduce yourself?'}</h2><p>Tell our team what you’re hoping to explore. Your details stay private while we review.</p></div><Field label="Why would you like to join TRENDIE MODELS?"><textarea maxLength={2000} rows={4} value={statement} onChange={e=>setStatement(e.target.value)} placeholder="A few words in your own voice"/></Field><div className="form-footer"><span>Application status: <Pill status={profile.application_status}/></span><Button disabled={submitApp.isPending}>{submitApp.isPending?'Submitting…':'Submit for review'} <ArrowRight size={16}/></Button></div></form> : null}
    <div className="panel portfolio-panel"><div><p className="section-kicker">PORTFOLIO MATERIALS</p><h2>Your work, thoughtfully presented.</h2><p>Uploads are kept in the agency’s private storage. Images only, up to 8 MB each.</p><StorageUpload profile={profile} kind="portfolio"/></div><StorageUpload profile={profile} kind="photo"/></div></div></div></>;
}

function StorageUpload({profile,kind}:{profile:AgencyProfile;kind:'photo'|'portfolio'}) {
  const qc=useQueryClient(); const update=useUpdateProfile(); const [status,setStatus]=useState(''); const [busy,setBusy]=useState(false); const bucket=import.meta.env.VITE_SUPABASE_STORAGE_BUCKET||'agency-private';
  const upload=async(e:ChangeEvent<HTMLInputElement>)=>{
    const file=e.target.files?.[0];e.target.value='';if(!file)return;
    if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setStatus('Choose a JPG, PNG, or WebP image.');return;}
    if(file.size>8*1024*1024){setStatus('This image is larger than 8 MB. Choose a smaller file.');return;}
    if(!supabase){setStatus('Private upload is not configured. Contact the agency team.');return;}
    setBusy(true);setStatus('Uploading securely…');
    try{
      const path=`${profile.id}/${kind}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
      const result=await supabase.storage.from(bucket).upload(path,file,{upsert:true,contentType:file.type});
      if(result.error)throw result.error;
      const next=kind==='photo'?{profile_photo_path:path}:{portfolio_paths:[...(profile.portfolio_paths||[]),path]};
      const saved=await update.mutateAsync({data:next});
      qc.setQueryData(getGetProfileQueryKey(),saved);setStatus('Upload complete. Your private profile was updated.');
    }catch(err){setStatus(err instanceof Error?err.message:'Upload failed. Please try again.');}
    finally{setBusy(false);}
  };
  return <div className={`storage-upload storage-${kind}`}><label className="upload-control"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={upload} disabled={busy}/><span className="upload-icon">{kind==='photo'?<Camera/>:<ImagePlus/>}</span><span><b>{kind==='photo'?'Profile portrait':'Add portfolio image'}</b><small>{kind==='photo'?(profile.profile_photo_path?'Replace current portrait':'No portrait uploaded yet'):`${profile.portfolio_paths?.length||0} image${profile.portfolio_paths?.length===1?'':'s'} in your portfolio`}</small></span><span className="upload-action">{busy?'Uploading…':'Choose file'}</span></label>{busy&&<progress className="upload-progress"/>}{status&&<p className={`upload-feedback ${status.includes('failed')||status.includes('Choose')||status.includes('larger')?'feedback-error':''}`} role="status">{status}</p>}<small className="upload-security"><ShieldCheck size={13}/> Private bucket · JPG, PNG, WebP · max 8 MB</small></div>;
}

function Models() {
  const [search,setSearch]=useState(''); const [status,setStatus]=useState('all');
  const q=useListModels({search:search||undefined,status:status as never});
  return <><PageTitle eyebrow="AGENCY ROSTER" title="Models" description="A considered view of the people in your agency."/><div className="toolbar"><label className="search-field"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name or email"/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All members</option><option value="approved">Approved</option><option value="pending">Pending</option><option value="rejected">Rejected</option><option value="suspended">Suspended</option></select></div>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="panel table-panel"><table><thead><tr><th>Model</th><th>Location</th><th>Status</th><th>Points</th><th>Joined</th></tr></thead><tbody>{q.data.map(m=><tr key={m.id}><td><div className="table-person"><span className="avatar">{initials(m.full_name)}</span><span><b>{m.full_name}</b><small>{m.email}</small></span></div></td><td>{m.location||'—'}</td><td><Pill status={m.suspended_at?'suspended':m.application_status}/></td><td>{m.points}</td><td>{fmt(m.created_at)}</td></tr>)}</tbody></table></div>:<EmptyState title="Your roster is ready to take shape." body={search?'No models match this search. Try another name or email.':'Approved applicants will appear here. No member records are shown until they exist in the agency.'}/>}</>;
}

function Applications() {
  const qc=useQueryClient(); const [filter,setFilter]=useState('pending'); const [review,setReview]=useState<{id:string;status:'approved'|'rejected'}|null>(null); const [reason,setReason]=useState('');
  const q=useListApplications({status:filter as never}); const mutation=useDecideApplication();
  const decide=(e:FormEvent)=>{e.preventDefault();if(!review)return;mutation.mutate({id:review.id,data:{status:review.status,reason}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListApplicationsQueryKey()});qc.invalidateQueries({queryKey:getListModelsQueryKey()});qc.invalidateQueries({queryKey:getGetDashboardQueryKey()});setReview(null);setReason('');}});};
  return <><PageTitle eyebrow="MEMBERSHIP REVIEW" title="Applications" description="Give every application a thoughtful, clear review."/><div className="tabs">{['pending','approved','rejected','all'].map(s=><button key={s} className={filter===s?'tab-active':''} onClick={()=>setFilter(s)}>{s[0].toUpperCase()+s.slice(1)}</button>)}</div>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="application-list">{q.data.map(a=><article className="panel application-card" key={a.id}><div className="application-person"><span className="avatar avatar-large">{initials(a.applicant?.full_name)}</span><div><h2>{a.applicant?.full_name||'Applicant'}</h2><p>{a.applicant?.email||'Account details unavailable'} · {a.applicant?.location||'Location not shared'}</p><small>Submitted {fmt(a.submitted_at)}</small></div><Pill status={a.status}/></div><div className="application-statement"><b>Why TRENDIE MODELS?</b><p>{a.statement||'No application statement was added.'}</p>{a.review_reason&&<div className="review-note"><b>Previous review note</b><p>{a.review_reason}</p></div>}</div>{a.status==='pending'&&<div className="application-actions"><Button variant="outline" onClick={()=>{setReview({id:a.id,status:'rejected'});setReason('');}}>Decline with a note</Button><Button onClick={()=>{setReview({id:a.id,status:'approved'});setReason('Approved to join the agency.');}}>Approve applicant <Check size={16}/></Button></div>}</article>)}</div>:<EmptyState title="No applications in this view." body="New applications will appear here for review. The list reflects live agency records."/>}
  {review&&<div className="modal-backdrop"><form className="modal" onSubmit={decide}><button type="button" className="modal-close" onClick={()=>setReview(null)} aria-label="Close"><X/></button><p className="section-kicker">APPLICATION DECISION</p><h2>{review.status==='approved'?'Welcome them in.':'Share a clear decision.'}</h2><p>Add a short reason or note for the applicant. This is shared with them.</p><Field label="Review note"><textarea required minLength={3} maxLength={1000} rows={4} value={reason} onChange={e=>setReason(e.target.value)} placeholder="A thoughtful note from the agency"/></Field><div className="modal-actions"><Button type="button" variant="outline" onClick={()=>setReview(null)}>Cancel</Button><Button disabled={mutation.isPending}>{mutation.isPending?'Saving…':`Confirm ${review.status}`} <ArrowRight size={15}/></Button></div></form></div>}</>;
}

function Tasks({ admin }: { admin:boolean }) {
  const qc=useQueryClient(); const q=useListTasks(); const models=useListModels({status:'approved'}); const create=useCreateTask(); const update=useUpdateTask(); const submit=useSubmitTask(); const review=useReviewSubmission();
  const [createOpen,setCreateOpen]=useState(false); const [taskId,setTaskId]=useState(''); const [notes,setNotes]=useState(''); const [reviewNote,setReviewNote]=useState(''); const [reviewPoints,setReviewPoints]=useState(''); const [reviewStatus,setReviewStatus]=useState<'approved'|'rejected'>('approved');
  const [evidenceFiles,setEvidenceFiles]=useState<File[]>([]); const [uploadNotice,setUploadNotice]=useState(''); const [uploadBusy,setUploadBusy]=useState(false);
  const [form,setForm]=useState({title:'',description:'',instructions:'',deadline:'',priority:'normal',assignment_user_ids:''});
  const invalidate=()=>{qc.invalidateQueries({queryKey:getListTasksQueryKey()});qc.invalidateQueries({queryKey:getGetDashboardQueryKey()});};
  const saveTask=(e:FormEvent)=>{e.preventDefault();create.mutate({data:{...form,deadline:form.deadline||null,priority:form.priority as never,assignment_user_ids:form.assignment_user_ids.split(',').map(x=>x.trim()).filter(Boolean)}},{onSuccess:()=>{invalidate();setCreateOpen(false);setForm({title:'',description:'',instructions:'',deadline:'',priority:'normal',assignment_user_ids:''});}});};
  const submitTask=async(task:AgencyTask,e:FormEvent)=>{e.preventDefault();if(!task.assignment_id)return;if(evidenceFiles.length>20){setUploadNotice('You can attach up to 20 files.');return;}setUploadNotice('');let paths:string[]=[];if(evidenceFiles.length){if(!supabase){setUploadNotice('Private file storage is not configured. Contact the agency team.');return;}setUploadBusy(true);try{for(const file of evidenceFiles){if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)){throw new Error('Attach JPG, PNG, WebP, or PDF files only.');}if(file.size>15*1024*1024){throw new Error('Each evidence file must be 15 MB or smaller.');}const bucket=import.meta.env.VITE_SUPABASE_STORAGE_BUCKET||'agency-private';const path=`${task.assignment_id}/submissions/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const result=await supabase.storage.from(bucket).upload(path,file,{upsert:true,contentType:file.type});if(result.error)throw result.error;paths.push(path);}setUploadNotice('Files uploaded privately. Sending your submission…');}catch(err){setUploadNotice(err instanceof Error?err.message:'An evidence file could not be uploaded.');setUploadBusy(false);return;}}
    try{await submit.mutateAsync({id:task.assignment_id,data:{notes:notes||null,evidence_paths:paths}});invalidate();setTaskId('');setNotes('');setEvidenceFiles([]);setUploadNotice('Your task has been submitted.');}catch(err){setUploadNotice(err instanceof Error?err.message:'Your submission could not be sent.');}finally{setUploadBusy(false);}};
  const reviewTask=(task:AgencyTask,e:FormEvent)=>{e.preventDefault();if(!task.assignment_id)return;review.mutate({id:task.assignment_id,data:{status:reviewStatus,review_note:reviewNote,points_awarded:Number(reviewPoints)||0}},{onSuccess:()=>{invalidate();setTaskId('');}});};
  return <><PageTitle title={admin?'Tasks & assignments':'My tasks'} eyebrow={admin?'AGENCY OPERATIONS':'YOUR ASSIGNMENTS'} description={admin?'Create assignments, review submissions, and keep expectations clear.':'Your assignments and submissions, all in one place.'} action={admin?<Button onClick={()=>setCreateOpen(true)}><Plus size={16}/> Create task</Button>:undefined}/>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="task-list">{q.data.map(task=><article className="panel task-card" key={task.id}><div className="task-card-head"><span className="task-check"><ClipboardList size={17}/></span><div><h2>{task.title}</h2><p>{task.description}</p></div><Pill status={task.assignment_status||task.status}/></div>{task.instructions&&<div className="task-instructions"><b>Instructions</b><p>{task.instructions}</p></div>}<div className="task-meta"><span><Clock3 size={15}/> {task.deadline?`Due ${fmt(task.deadline)}`:'No deadline'}</span><span className={`priority priority-${task.priority}`}>{task.priority} priority</span></div>{task.submission&&<div className="submission-preview"><b>Submission</b><p>{String(task.submission['notes']||'Evidence submitted for review.')}</p>{!!task.submission['status']&&<Pill status={String(task.submission['status'])}/>}</div>}
      {!admin && ['open','in_progress'].includes(task.assignment_status||'')&&<form className="inline-submit task-submit-form" onSubmit={e=>submitTask(task,e)}><Field label="Submission notes"><textarea value={taskId===task.id?notes:''} onChange={e=>{setTaskId(task.id);setNotes(e.target.value);}} rows={2} placeholder="Add context for your submission"/></Field><label className="task-upload"><input type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" onChange={e=>{setTaskId(task.id);setEvidenceFiles(Array.from(e.target.files||[]));setUploadNotice('');}}/><span><ImagePlus size={15}/> Attach evidence</span><small>{taskId===task.id&&evidenceFiles.length?evidenceFiles.map(f=>f.name).join(', '):'Images or PDF · 15 MB max each'}</small></label>{taskId===task.id&&uploadNotice&&<p className="upload-feedback">{uploadNotice}</p>}{uploadBusy&&<progress className="upload-progress"/>}<Button disabled={submit.isPending||uploadBusy||!task.assignment_id}>{uploadBusy?'Uploading…':submit.isPending?'Submitting…':'Submit task'} <ArrowRight size={15}/></Button></form>}
      {admin&&task.assignment_status==='submitted'&&<form className="inline-submit review-form" onSubmit={e=>reviewTask(task,e)}><Field label="Review note"><input required value={taskId===task.id?reviewNote:''} onChange={e=>{setTaskId(task.id);setReviewNote(e.target.value);}} placeholder="Feedback for this model"/></Field><Field label="Points"><input type="number" min="0" max="10000" value={taskId===task.id?reviewPoints:''} onChange={e=>{setTaskId(task.id);setReviewPoints(e.target.value);}}/></Field><select value={reviewStatus} onChange={e=>setReviewStatus(e.target.value as 'approved'|'rejected')}><option value="approved">Approve</option><option value="rejected">Request changes</option></select><Button disabled={review.isPending}>Save review</Button></form>}
      {admin&&task.status!=='completed'&&task.status!=='cancelled'&&<div className="task-admin-controls"><Button variant="quiet" onClick={()=>update.mutate({id:task.id,data:{status:'cancelled'}},{onSuccess:invalidate})}>Cancel assignment</Button></div>}
    </article>)}</div>:<EmptyState title={admin?'No tasks have been assigned yet.':'Nothing on your task list.'} body={admin?'Create a task when the team has a clear goal for members.':'When the agency assigns you something, it will appear here.'} action={admin?<Button onClick={()=>setCreateOpen(true)}><Plus size={16}/> Create a task</Button>:undefined}/>}
    {createOpen&&<div className="modal-backdrop"><form className="modal modal-wide" onSubmit={saveTask}><button type="button" className="modal-close" onClick={()=>setCreateOpen(false)} aria-label="Close"><X/></button><p className="section-kicker">NEW ASSIGNMENT</p><h2>Make the next step clear.</h2><div className="form-grid"><Field label="Task title"><input required minLength={2} maxLength={160} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Priority"><select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></Field><Field label="Description"><textarea required rows={3} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Instructions (optional)"><textarea rows={3} value={form.instructions} onChange={e=>setForm({...form,instructions:e.target.value})}/></Field><Field label="Deadline"><input type="date" value={form.deadline} onChange={e=>setForm({...form,deadline:e.target.value})}/></Field><Field label="Assignee user IDs (comma separated)"><input value={form.assignment_user_ids} onChange={e=>setForm({...form,assignment_user_ids:e.target.value})} placeholder="Paste IDs of approved models"/><small>Use the model user IDs from the roster. Leave blank to create an unassigned task.</small></Field></div>{models.isError&&<p className="quiet-line">Could not load model IDs. Use the Models roster and retry.</p>}<div className="modal-actions"><Button type="button" variant="outline" onClick={()=>setCreateOpen(false)}>Cancel</Button><Button disabled={create.isPending}>{create.isPending?'Creating…':'Create task'} <ArrowRight size={15}/></Button></div></form></div>}</>;
}

function Points({ admin }: { admin:boolean }) {
  const qc=useQueryClient(); const leaderboard=useGetLeaderboard(); const points=useListPoints(); const models=useListModels({status:'approved'}); const award=useAwardPoints();
  const [open,setOpen]=useState(false); const [form,setForm]=useState({model_id:'',delta:'',reason:''});
  const submit=(e:FormEvent)=>{e.preventDefault();award.mutate({data:{model_id:form.model_id,delta:Number(form.delta),reason:form.reason}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListPointsQueryKey()});qc.invalidateQueries({queryKey:getGetLeaderboardQueryKey()});qc.invalidateQueries({queryKey:getListModelsQueryKey()});setOpen(false);setForm({model_id:'',delta:'',reason:''});}});};
  return <><PageTitle eyebrow={admin?'COMMUNITY RECOGNITION':'YOUR PROGRESS'} title={admin?'Points & leaderboard':'Points & ranking'} description={admin?'Recognise contributions and see how the community is growing.':'Every point marks a step forward. See your place in the community.'} action={admin?<Button onClick={()=>setOpen(true)}><Plus size={16}/> Award points</Button>:undefined}/><div className="points-layout"><section className="panel leaderboard-panel"><div className="panel-head"><div><p className="section-kicker">COMMUNITY BOARD</p><h2>Leaderboard</h2></div><Trophy className="panel-head-icon"/></div>{leaderboard.isLoading?<LoadingState/>:leaderboard.isError?<ErrorState retry={()=>leaderboard.refetch()}/>:leaderboard.data?.length?<div className="leaderboard-list">{leaderboard.data.map((entry,i)=><div className={`leader-row ${i<3?'leader-top':''}`} key={entry.user_id}><b className="rank-no">{String(entry.rank).padStart(2,'0')}</b><span className="avatar">{initials(entry.full_name)}</span><span className="leader-name">{entry.full_name}</span><span className="leader-score">{entry.points}<small> pts</small></span>{i===0&&<span className="leader-badge">LEADING</span>}</div>)}</div>:<EmptyState title="The first place is still open." body="There are no leaderboard entries yet. As members earn points, they’ll show here."/>}</section><section className="panel points-history"><div className="panel-head"><div><p className="section-kicker">{admin?'RECENT TRANSACTIONS':'YOUR ACTIVITY'}</p><h2>Points history</h2></div></div>{points.isLoading?<LoadingState/>:points.isError?<ErrorState retry={()=>points.refetch()}/>:points.data?.length?points.data.map(p=><div className="points-row" key={p.id}><span className={`delta ${p.delta>=0?'delta-plus':'delta-minus'}`}>{p.delta>0?'+':''}{p.delta}</span><span><b>{p.reason}</b><small>{admin?p.model_id:'Agency points'}</small></span><time>{fmt(p.created_at)}</time></div>):<EmptyState title="Your points start here." body="Points from agency activity will be recorded here. Nothing is added until it’s earned or awarded."/>}</section></div>
    {open&&<div className="modal-backdrop"><form className="modal" onSubmit={submit}><button type="button" className="modal-close" onClick={()=>setOpen(false)} aria-label="Close"><X/></button><p className="section-kicker">RECOGNISE THE WORK</p><h2>A little encouragement goes far.</h2><Field label="Approved model"><select required value={form.model_id} onChange={e=>setForm({...form,model_id:e.target.value})}><option value="">Choose a member</option>{models.data?.map(m=><option value={m.id} key={m.id}>{m.full_name} · {m.email}</option>)}</select></Field><Field label="Point change"><input type="number" min="-10000" max="10000" required value={form.delta} onChange={e=>setForm({...form,delta:e.target.value})}/></Field><Field label="Reason"><textarea required minLength={3} maxLength={1000} value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} rows={3}/></Field><div className="modal-actions"><Button variant="outline" type="button" onClick={()=>setOpen(false)}>Cancel</Button><Button disabled={award.isPending}>Award points <ArrowRight size={15}/></Button></div></form></div>}</>;
}

function Announcements({ admin }: { admin:boolean }) {
  const qc=useQueryClient(); const q=useListAnnouncements(); const create=useCreateAnnouncement(); const update=useUpdateAnnouncement(); const mark=useMarkAnnouncementRead();
  const [open,setOpen]=useState(false); const [editing,setEditing]=useState<string|null>(null); const [form,setForm]=useState({title:'',body:'',status:'published',audience:'all'});
  const reset=()=>{setOpen(false);setEditing(null);setForm({title:'',body:'',status:'published',audience:'all'});};
  const save=(e:FormEvent)=>{e.preventDefault();const data={...form,status:form.status as 'draft'|'published',audience:form.audience as 'all'|'selected',recipient_ids:[]};const onSuccess=()=>{qc.invalidateQueries({queryKey:getListAnnouncementsQueryKey()});reset();};if(editing)update.mutate({id:editing,data},{onSuccess});else create.mutate({data},{onSuccess});};
  return <><PageTitle eyebrow={admin?'COMMUNITY COMMS':'AGENCY BULLETIN'} title="Announcements" description={admin?'Keep the agency connected with clear, timely updates.':'News and notes from the TRENDIE MODELS team.'} action={admin?<Button onClick={()=>setOpen(true)}><Plus size={16}/> New announcement</Button>:undefined}/>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="announcement-list">{q.data.map(a=><article className="panel announcement-card" key={a.id}><div className="announcement-card-top"><span className="announcement-mark"><BookOpen/></span><Pill status={a.status}/><small>{fmt(a.published_at||a.created_at)}</small></div><h2>{a.title}</h2><p>{a.body}</p><div className="announcement-card-foot">{!admin&&!a.is_read&&<Button variant="outline" onClick={()=>mark.mutate({id:a.id},{onSuccess:()=>qc.invalidateQueries({queryKey:getListAnnouncementsQueryKey()})})}>Mark as read <Check size={14}/></Button>}{admin&&<div className="announcement-admin"><span>Audience: {a.audience}</span><Button variant="quiet" onClick={()=>{setEditing(a.id);setForm({title:a.title,body:a.body,status:a.status==='archived'?'draft':a.status,audience:a.audience});setOpen(true);}}>Edit</Button>{a.status!=='archived'&&<Button variant="quiet" onClick={()=>update.mutate({id:a.id,data:{status:'archived'}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListAnnouncementsQueryKey()})})}>Archive</Button>}</div>}</div></article>)}</div>:<EmptyState title="No announcements yet." body={admin?'When the team shares an update, it will appear here.':'When the agency has news to share, it will appear here.'} action={admin?<Button onClick={()=>setOpen(true)}><Plus size={15}/> Write an update</Button>:undefined}/>}
    {open&&<div className="modal-backdrop"><form className="modal modal-wide" onSubmit={save}><button type="button" className="modal-close" onClick={reset} aria-label="Close"><X/></button><p className="section-kicker">AGENCY BULLETIN</p><h2>{editing?'Edit announcement':'Share an update.'}</h2><Field label="Headline"><input required minLength={2} maxLength={160} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Message"><textarea required minLength={2} maxLength={8000} rows={6} value={form.body} onChange={e=>setForm({...form,body:e.target.value})}/></Field><div className="form-grid"><Field label="Status"><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="published">Publish now</option><option value="draft">Save draft</option></select></Field><Field label="Audience"><select value={form.audience} onChange={e=>setForm({...form,audience:e.target.value})}><option value="all">All members</option><option value="selected">Selected members</option></select></Field></div><p className="quiet-line">Selected audience targeting requires member IDs; use All members until recipients are selected.</p><div className="modal-actions"><Button variant="outline" type="button" onClick={reset}>Cancel</Button><Button disabled={create.isPending||update.isPending}>Save announcement <ArrowRight size={15}/></Button></div></form></div>}</>;
}

function Messages({ profile, admin }: { profile:AgencyProfile; admin:boolean }) {
  const qc=useQueryClient(); const conv=useListConversations(); const [selected,setSelected]=useState(''); const [body,setBody]=useState(''); const [recipient,setRecipient]=useState(''); const [title,setTitle]=useState(''); const [firstMessage,setFirstMessage]=useState('');
  const create=useCreateConversation(); const send=useSendMessage(); const messageQuery=useListMessages(selected,{query:{enabled:!!selected,queryKey:getListMessagesQueryKey(selected)}});
  const messages=messageQuery.data||[];
  const start=(e:FormEvent)=>{e.preventDefault();create.mutate({data:{recipient_id:recipient,title:title||null,initial_message:firstMessage}},{onSuccess:c=>{qc.invalidateQueries({queryKey:getListConversationsQueryKey()});setSelected(c.id);setRecipient('');setTitle('');setFirstMessage('');}});};
  const sendMessage=(e:FormEvent)=>{e.preventDefault();if(!selected||!body.trim())return;send.mutate({id:selected,data:{body:body.trim()}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListMessagesQueryKey(selected)});qc.invalidateQueries({queryKey:getListConversationsQueryKey()});setBody('');}});};
  return <><PageTitle eyebrow="PRIVATE AGENCY CHANNEL" title="Messages" description="A direct, private line between you and the TRENDIE MODELS team."/><div className="messages-layout"><aside className="panel conversation-list"><div className="conversation-head"><h2>Conversations</h2><span>{conv.data?.length||0}</span></div>{conv.isLoading?<LoadingState/>:conv.isError?<ErrorState retry={()=>conv.refetch()}/>:conv.data?.length?conv.data.map(c=><button className={`conversation-item ${selected===c.id?'conversation-selected':''}`} key={c.id} onClick={()=>setSelected(c.id)}><span className="avatar"><MessageCircle size={16}/></span><span><b>{c.title||'Agency conversation'}</b><small>{c.unread_count?`${c.unread_count} unread`:'No unread messages'}</small></span><ChevronRight size={16}/></button>):<EmptyState title="No conversations yet." body="A conversation will appear here when you or the agency starts one."/>}</aside>
    <section className="panel message-panel">{selected?<><div className="message-head"><span className="avatar"><MessageCircle size={16}/></span><div><b>{conv.data?.find(c=>c.id===selected)?.title||'Agency conversation'}</b><small>Private conversation</small></div></div><div className="message-thread">{messageQuery.isLoading?<LoadingState/>:messageQuery.isError?<ErrorState retry={()=>messageQuery.refetch()}/>:messages.length?messages.map(m=><div className={`message-bubble ${m.sender_id===profile.id?'message-mine':''}`} key={m.id}><p>{m.body}</p><small>{m.sender_id===profile.id?'You':'Agency team'} · {fmt(m.created_at)}</small></div>):<EmptyState title="A fresh conversation." body="Send a note to begin."/>}</div><form className="message-compose" onSubmit={sendMessage}><input required maxLength={4000} value={body} onChange={e=>setBody(e.target.value)} placeholder="Write a message to the agency…"/><Button aria-label="Send message" disabled={send.isPending}><Send size={17}/></Button></form></>:<div className="message-empty"><span><Inbox/></span><h2>Make room for a conversation.</h2><p>Select a thread or start a new private conversation.</p></div>}</section></div>
    <form className="panel new-conversation" onSubmit={start}><div><p className="section-kicker">START A PRIVATE THREAD</p><h2>Send a first note</h2><p>Choose a recipient using their member ID. The agency will provide this if you need it.</p></div><div className="new-convo-fields"><Field label="Recipient member ID"><input required value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder={admin?'Model user ID':'Agency team user ID'}/></Field><Field label="Subject (optional)"><input maxLength={160} value={title} onChange={e=>setTitle(e.target.value)} placeholder="What would you like to discuss?"/></Field><Field label="First message"><input required minLength={1} maxLength={4000} value={firstMessage} onChange={e=>setFirstMessage(e.target.value)} placeholder="Write your opening message"/></Field><Button disabled={create.isPending}>{create.isPending?'Starting…':'Start conversation'} <ArrowRight size={15}/></Button></div></form></>;
}

function Notifications() {
  const qc=useQueryClient(); const q=useListNotifications(); const mark=useMarkNotificationsRead();
  const unread=q.data?.filter(n=>!n.is_read).map(n=>n.id)||[];
  return <><PageTitle title="Notifications" description="Important updates from your agency, in one place." action={unread.length?<Button variant="outline" onClick={()=>mark.mutate({data:{ids:unread}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListNotificationsQueryKey()})})} disabled={mark.isPending}>Mark all read <Check size={15}/></Button>:undefined}/>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="notification-list">{q.data.map(n=><article className={`panel notification-card ${n.is_read?'notification-read':''}`} key={n.id}><span className="notification-mark"><Bell size={17}/></span><div><div className="notification-heading"><h2>{n.title}</h2>{!n.is_read&&<i/>}</div>{n.body&&<p>{n.body}</p>}<small>{fmt(n.created_at)} · {n.kind}</small></div>{n.link&&<Link href={n.link} className="panel-link">Open <ArrowUpRight size={15}/></Link>}</article>)}</div>:<EmptyState title="All caught up." body="New agency updates and reminders will find their way here."/>}</>;
}

function Tracker() {
  const qc=useQueryClient(); const q=useListDailyEntries(); const save=useSaveDailyEntry();
  const today=new Date().toLocaleDateString('en-CA'); const existing=q.data?.find(entry=>entry.entry_date===today);
  const [checked,setChecked]=useState(false); const [water,setWater]=useState(0); const [wellness,setWellness]=useState<string[]>([]); const [notes,setNotes]=useState('');
  useEffect(()=>{if(existing){setChecked(existing.checked_in);setWater(existing.water_glasses);setWellness(existing.wellness||[]);setNotes(existing.notes||'');}},[existing]);
  const choices=['Movement','Rest','Stretching','Mindfulness'];
  const saveEntry=(e:FormEvent)=>{e.preventDefault();save.mutate({data:{entry_date:today,checked_in:checked,water_glasses:water,measurements:existing?.measurements||{},wellness,notes:notes||null}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListDailyEntriesQueryKey()})});};
  return <><PageTitle eyebrow="A SMALL DAILY CHECK-IN" title="Daily tracker" description="Notice the habits that help you feel prepared, present, and well."/><div className="tracker-grid"><form className="panel tracker-form" onSubmit={saveEntry}><div className="tracker-date"><span><CalendarDays/></span><div><p className="section-kicker">TODAY</p><h2>{new Date().toLocaleDateString('en-GH',{weekday:'long',month:'long',day:'numeric'})}</h2></div></div><label className="checkin-toggle"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/><span className="custom-check"><Check size={14}/></span><span><b>Check in for today</b><small>One small step, logged for you.</small></span></label><div className="water-control"><div><Droplets/><span><b>Water</b><small>Glasses today</small></span></div><div className="stepper"><button type="button" onClick={()=>setWater(Math.max(0,water-1))} aria-label="Remove glass">−</button><b>{water}</b><button type="button" onClick={()=>setWater(Math.min(50,water+1))} aria-label="Add glass">+</button></div></div><div className="wellness-field"><b>What supported you today?</b><div className="choice-chips">{choices.map(choice=><button type="button" className={wellness.includes(choice)?'chip-selected':''} onClick={()=>setWellness(wellness.includes(choice)?wellness.filter(w=>w!==choice):[...wellness,choice])} key={choice}>{wellness.includes(choice)&&<Check size={12}/>} {choice}</button>)}</div></div><Field label="Notes for yourself (optional)"><textarea rows={4} maxLength={2000} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Anything worth remembering about today?"/></Field><div className="form-footer"><span>{existing?'Your entry is saved for today.':'Your check-in is private to your account.'}</span><Button disabled={save.isPending}>{save.isPending?'Saving…':'Save today’s entry'} <Check size={15}/></Button></div></form><aside className="panel tracker-history"><p className="section-kicker">RECENT CHECK-INS</p><h2>Showing up, day by day.</h2>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?q.data.slice(0,7).map(entry=><div className="tracker-history-row" key={entry.id}><span className={entry.checked_in?'history-checked':''}>{entry.checked_in?<Check size={14}/>:<span/>}</span><b>{fmt(entry.entry_date)}</b><small>{entry.water_glasses} glasses</small></div>):<EmptyState title="Your first check-in is waiting." body="A little daily attention can make a difference. Nothing has been recorded yet."/>}</aside></div></>;
}

function Support({admin}:{admin:boolean}) {
  const qc=useQueryClient(); const q=useListSupportRequests(); const create=useCreateSupportRequest(); const update=useUpdateSupportRequest(); const reply=useReplyToSupportRequest();
  const [open,setOpen]=useState(false); const [subject,setSubject]=useState(''); const [message,setMessage]=useState(''); const [replyText,setReplyText]=useState<Record<string,string>>({});
  const submit=(e:FormEvent)=>{e.preventDefault();create.mutate({data:{subject,message}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListSupportRequestsQueryKey()});setOpen(false);setSubject('');setMessage('');}});};
  const sendReply=(id:string,e:FormEvent)=>{e.preventDefault();const body=replyText[id]?.trim();if(!body)return;reply.mutate({id,data:{body}},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListSupportRequestsQueryKey()});setReplyText({...replyText,[id]:''});}});};
  return <><PageTitle eyebrow={admin?'AGENCY CARE':'WE’RE HERE TO HELP'} title={admin?'Support requests':'Support'} description={admin?'Follow through on requests with clear status updates and replies.':'Ask a question or let the agency team know what you need.'} action={!admin?<Button onClick={()=>setOpen(true)}><Plus size={16}/> New request</Button>:undefined}/>{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="support-list">{q.data.map(request=><article className="panel support-card" key={request.id}><div className="support-head"><div><p className="section-kicker">REQUEST · {fmt(request.created_at)}</p><h2>{request.subject}</h2></div>{admin?<select value={request.status} onChange={e=>update.mutate({id:request.id,data:{status:e.target.value as never}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListSupportRequestsQueryKey()})})}><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select>:<Pill status={request.status}/>}</div><div className="support-thread">{request.replies?.length?request.replies.map(r=><div className="support-reply" key={r.id}><span className="avatar">{initials(r.author_id===request.user_id?'You':'TM')}</span><div><p>{r.body}</p><small>{fmt(r.created_at)} · {r.author_id===request.user_id?'You':'Agency team'}</small></div></div>):<p className="quiet-line">The conversation is just beginning. The team will reply here.</p>}</div><form className="support-reply-form" onSubmit={e=>sendReply(request.id,e)}><input required maxLength={4000} value={replyText[request.id]||''} onChange={e=>setReplyText({...replyText,[request.id]:e.target.value})} placeholder="Write a reply…"/><Button variant="outline" disabled={reply.isPending}><Send size={15}/> Reply</Button></form></article>)}</div>:<EmptyState title={admin?'No requests are waiting.':'A helpful team is one message away.'} body={admin?'Support requests will appear here when members ask for help.':'Create a request and the agency team will follow up with you here.'} action={!admin?<Button onClick={()=>setOpen(true)}><Plus size={15}/> Create a request</Button>:undefined}/>}
    {open&&<div className="modal-backdrop"><form className="modal" onSubmit={submit}><button type="button" className="modal-close" onClick={()=>setOpen(false)} aria-label="Close"><X/></button><p className="section-kicker">MEMBER SUPPORT</p><h2>How can we help?</h2><Field label="Subject"><input required minLength={3} maxLength={160} value={subject} onChange={e=>setSubject(e.target.value)} placeholder="A short summary"/></Field><Field label="Message"><textarea required minLength={3} maxLength={4000} rows={5} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Share the details that will help us support you"/></Field><div className="modal-actions"><Button variant="outline" type="button" onClick={()=>setOpen(false)}>Cancel</Button><Button disabled={create.isPending}>{create.isPending?'Sending…':'Send request'} <ArrowRight size={15}/></Button></div></form></div>}</>;
}

function Audit() {
  const q=useListAuditLogs();
  return <><PageTitle eyebrow="AGENCY OVERSIGHT" title="Audit log" description="A record of actions across the agency. Access is restricted to administrators."/><section className="panel audit-panel">{q.isLoading?<LoadingState/>:q.isError?<ErrorState retry={()=>q.refetch()}/>:q.data?.length?<div className="audit-list">{q.data.map(event=><article className="audit-row" key={event.id}><span className="audit-icon"><ShieldCheck size={16}/></span><div><b>{event.action.replaceAll('_',' ')}</b><small>{event.entity_type}{event.entity_id?` · ${event.entity_id}`:''}</small></div><time>{fmt(event.created_at)}</time><details><summary>Details</summary><pre>{JSON.stringify(event.details,null,2)}</pre></details></article>)}</div>:<EmptyState title="No events have been recorded." body="Actions will appear here as the agency workspace is used. Nothing is being generated for an empty project."/>}</section></>;
}

function SettingsPage({profile}:{profile:AgencyProfile}) {
  const stats=useGetAdminStats({query:{enabled:profile.role==='admin',queryKey:getGetAdminStatsQueryKey()}});
  const [,go]=useLocation();
  return <><PageTitle eyebrow="WORKSPACE PREFERENCES" title="Settings" description="Account and agency workspace details."/><div className="settings-grid"><section className="panel settings-card"><div className="panel-head"><div><p className="section-kicker">YOUR ACCOUNT</p><h2>Profile &amp; access</h2></div><UserRound/></div><p>Your profile information is managed in your member profile. Your account role is controlled by the agency and cannot be changed here.</p><Link href="/profile" className="button button-outline">Edit profile <ArrowRight size={15}/></Link><div className="settings-detail"><small>Signed in as</small><b>{profile.email}</b><small>Agency role</small><b>{profile.role==='admin'?'Administrator':'Model member'}</b></div></section><section className="panel settings-card"><div className="panel-head"><div><p className="section-kicker">AGENCY CONTACT</p><h2>Reach the team</h2></div><Mail/></div><p>Questions about your account or agency experience? Contact the team directly.</p><a className="contact-email" href="mailto:hellotrendiemodels@gmail.com">hellotrendiemodels@gmail.com <ExternalLink size={15}/></a><small>Accra, Ghana · Applicant and member support</small></section>{profile.role==='admin'&&<section className="panel settings-card admin-settings"><div className="panel-head"><div><p className="section-kicker">LIVE AGENCY COUNTS</p><h2>Workspace status</h2></div><Activity/></div>{stats.isLoading?<LoadingState/>:stats.isError?<ErrorState retry={()=>stats.refetch()}/>:stats.data?<div className="settings-stats"><span><b>{stats.data.total_models}</b><small>Total models</small></span><span><b>{stats.data.pending_applications}</b><small>Pending applications</small></span><span><b>{stats.data.open_support_requests}</b><small>Open requests</small></span></div>:<p className="quiet-line">No stats returned from the agency API.</p>}<p className="quiet-line">Counts come from agency records; this view does not create or modify settings that the API does not support.</p></section>}<section className="panel settings-card"><div className="panel-head"><div><p className="section-kicker">SESSION</p><h2>Sign out safely</h2></div><ShieldCheck/></div><p>End your current session on this device. You can sign back in at any time.</p><Button variant="outline" onClick={async()=>{await supabase?.auth.signOut();go('/');}}><LogOut size={16}/> Sign out</Button></section></div></>;
}
